package com.opencrm.ai.experiment;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * Create a rule A/B experiment. When {@code variants} is empty, challengers are
 * generated by mutating decimal literals in the source rule DRL.
 */
public record CreateExperimentRequest(
        @NotNull Long ruleId,
        @NotBlank String name,
        String description,
        @Min(0) @Max(1) Double controlTrafficPct,
        @Min(1) @Max(10) Integer challengerCount,
        List<VariantSeed> variants
) {
    public record VariantSeed(
            @NotBlank String name,
            String description,
            @NotBlank String ruleContent
    ) {
    }
}
